import "fmt"

type Tree struct {
	Value       int
	Left, Right *Tree
}

func insert(t *Tree, v int) *Tree {
	if t == nil {
		return &Tree{Value: v}
	}
	if v < t.Value {
		t.Left = insert(t.Left, v)
	} else {
		t.Right = insert(t.Right, v)
	}
	return t
}

func walk(t *Tree) {
	if t == nil {
		return
	}
	walk(t.Left)
	fmt.Print(t.Value, " ")
	walk(t.Right)
}

func main() {
	var root *Tree
	for _, v := range []int{5, 2, 8, 1, 9, 3} {
		root = insert(root, v)
	}
	walk(root)
	fmt.Println()
}

