package main

import "fmt"

type Stats struct {
	Min, Max int
	Avg      float64
}

func analyze(nums []int) Stats {
	s := Stats{Min: nums[0], Max: nums[0]}
	sum := 0
	for _, n := range nums {
		s.Min = min(s.Min, n)
		s.Max = max(s.Max, n)
		sum += n
	}
	s.Avg = float64(sum) / float64(len(nums))
	return s
}

func main() {
	st := analyze([]int{4, 8, 15, 16, 23, 42})
	fmt.Println("eng kichik:", st.Min)
	fmt.Println("eng katta:", analyze([]int{3, 9, 1}).Max)
	fmt.Printf("%+v\n", st)
}

