import "fmt"

type Items []int

func (it Items) Len() int { return len(it) }

type Stack struct {
	Items
}

func (s *Stack) Push(v int) { s.Items = append(s.Items, v) }

func (s *Stack) Pop() int {
	last := s.Items[len(s.Items)-1]
	s.Items = s.Items[:len(s.Items)-1]
	return last
}

func main() {
	var s Stack
	s.Push(10)
	s.Push(20)
	s.Push(30)
	fmt.Println(s.Len(), s.Pop(), s.Len())
}

