import (
	"fmt"
	"reflect"
	"strings"
)

type Signup struct {
	Name  string `validate:"required,min=3"`
	Email string `validate:"required"`
	Bio   string
}

func validate(v any) []string {
	var problems []string
	rv := reflect.ValueOf(v)
	rt := rv.Type()
	for i := 0; i < rt.NumField(); i++ {
		field := rt.Field(i)
		rules, ok := field.Tag.Lookup("validate")
		if !ok {
			continue
		}
		value := rv.Field(i).String()
		for _, rule := range strings.Split(rules, ",") {
			switch {
			case rule == "required" && value == "":
				problems = append(problems, field.Name+" majburiy")
			case strings.HasPrefix(rule, "min="):
				var n int
				fmt.Sscanf(rule, "min=%d", &n)
				if value != "" && len(value) < n {
					problems = append(problems, fmt.Sprintf("%s kamida %d belgi bo'lishi kerak", field.Name, n))
				}
			}
		}
	}
	return problems
}

func main() {
	for _, p := range validate(Signup{Name: "Al"}) {
		fmt.Println(p)
	}
}

