	Score int `range:"0-100"`
}

func checkRanges(v any) {
	rv := reflect.ValueOf(v)
	for i := 0; i < rv.NumField(); i++ {
		f := rv.Type().Field(i)
		rule := f.Tag.Get("range")
		if rule == "" {
			continue
		}
		lo, hi, _ := strings.Cut(rule, "-")
		low, _ := strconv.Atoi(lo)
		high, _ := strconv.Atoi(hi)
		n := int(rv.Field(i).Int())

		status := "OK"
		if n < low || n > high {
			status = "chegaradan tashqari"
		}
		fmt.Printf("%s=%d: %s\n", f.Name, n, status)
	}
}

