	Price   float64 `db:"price"`
	InStock bool    `db:"in_stock"`
}

func createSQL(table string, v any) string {
	t := reflect.TypeOf(v)
	var cols []string
	for i := 0; i < t.NumField(); i++ {
		f := t.Field(i)
		col := f.Tag.Get("db")
		if col == "" {
			continue
		}
		typ := "TEXT"
		switch f.Type.Kind() {
		case reflect.Int, reflect.Int64:
			typ = "INTEGER"
		case reflect.Float64:
			typ = "REAL"
		case reflect.Bool:
			typ = "BOOLEAN"
		}
		cols = append(cols, col+" "+typ)
	}
	return "CREATE TABLE " + table + " (" + strings.Join(cols, ", ") + ")"
}

func main() {
	fmt.Println(createSQL("products", Product{}))
}

