		{"manfiy", -9, 3, -3, false},
	}

	for _, tc := range tests {
		got, err := divide(tc.a, tc.b)
		ok := got == tc.want && (err != nil) == tc.wantErr
		fmt.Printf("%s: %t\n", tc.name, ok)
	}
}

