func minMax(nums []int) struct{ Min, Max int } {
	res := struct{ Min, Max int }{nums[0], nums[0]}
	for _, n := range nums {
		res.Min = min(res.Min, n)
		res.Max = max(res.Max, n)
	}
	return res
}

