import (
	"fmt"
	"sort"
)

type Sale struct {
	Region string
	Month  string
	Amount int
}

type key struct{ Region, Month string }

func main() {
	sales := []Sale{
		{"Toshkent", "yanvar", 100},
		{"Samarqand", "yanvar", 50},
		{"Toshkent", "yanvar", 200},
		{"Toshkent", "fevral", 70},
		{"Samarqand", "yanvar", 25},
	}

	totals := map[key]int{}
	for _, s := range sales {
		totals[key{s.Region, s.Month}] += s.Amount
	}

	keys := make([]key, 0, len(totals))
	for k := range totals {
		keys = append(keys, k)
	}
	sort.Slice(keys, func(i, j int) bool {
		if keys[i].Region != keys[j].Region {
			return keys[i].Region < keys[j].Region
		}
		return keys[i].Month < keys[j].Month
	})
	for _, k := range keys {
		fmt.Printf("%-10s %-7s %d\n", k.Region, k.Month, totals[k])
	}
}

