import "fmt"

type cell struct{ r, c int }

var memo = map[cell]int{}

// paths: r x c to'rda yuqori-chapdan pastki-o'ngga yo'llar soni
func paths(r, c int) int {
	if r == 1 || c == 1 {
		return 1
	}
	k := cell{r, c}
	if v, ok := memo[k]; ok {
		return v
	}
	memo[k] = paths(r-1, c) + paths(r, c-1)
	return memo[k]
}

func main() {
	fmt.Println(paths(3, 3))
	fmt.Println(paths(7, 3))
	fmt.Println(paths(18, 18), len(memo) > 0)
}

